6	export const CARD_RETURNED_EVENT_NAME = "card.returned" as const;
7	
8	export interface CardReturnedParams {
9	  /** The Spine's real table id (the full slug), matching seat.joined's `entry.spineTableId`. */
10	  tableId: string;
11	  seatId: string;
12	  playerName: string;
13	  scryfallId: string;
14	  gameCardIndex: number;
15	  fromZone?: string;
16	}
17	
18	/**
19	 * Sends a `card.returned.v1` event to the Spine's generic events endpoint — the same send
20	 * shape `sendCardPlayedToSpineBestEffort` (Shuffler) already uses for `card.played`, and
21	 * `eventsUrl` is not introduced: the address is simply "the Spine". Rides the ambient
22	 * request/gesture span plus undici's automatic outbound `traceparent` header; no envelope
23	 * `traceparent` is minted here. Best-effort: never throws or rejects — a Spine failure
24	 * never crashes the caller. Resolves `true`/`false` so a send-then-commit caller (the
25	 * library-portal swallow, ticket 12) can gate its own commit on the outcome; both outcomes
26	 * are stamped on the active span (`card.returned.spine_confirmed`), and failure also sets
27	 * `spine_send.send_failed` and logs a warning. Bounded to a 5s timeout
28	 * (`AbortSignal.timeout`) — unlike `spineSubscriber.ts`'s long-lived SSE connection this
29	 * is a single request, so a plain abort signal is enough; no `undici.Agent` needed.
30	 */
31	export async function sendCardReturnedToSpineBestEffort(
32	  params: CardReturnedParams,
33	  baseUrl: string = process.env.SPINE_URL || "http://localhost:4600"
34	): Promise<boolean> {
35	  const { tableId, seatId, playerName, scryfallId, gameCardIndex, fromZone } = params;
36	  const event = {
37	    id: randomUUID(),
38	    tableId,
39	    name: CARD_RETURNED_EVENT_NAME,
40	    occurredAt: new Date().toISOString(),
41	    initiator: { seatId, playerName },
42	    occurredIn: "tabletop" as const,
43	    origin: "tabletop.cardShapeHook",
44	    significance: "domain" as const,
45	    schemaVersion: 1,
46	    payload: {
47	      card: { scryfallId },
48	      gameCardIndex,
49	      seat: seatId,
50	      ...(fromZone !== undefined ? { fromZone } : {}),
51	    },
52	  };
53	
54	  try {
55	    const url = `${baseUrl}/tables/${encodeURIComponent(tableId)}/events`;
56	    const response = await fetch(url, {
57	      method: "POST",
58	      headers: { "content-type": "application/json" },
59	      body: JSON.stringify(event),
60	      signal: AbortSignal.timeout(5000),
61	    });
62	    if (!response.ok) {
63	      const bodyText = await response.text().catch(() => "");
64	      throw new Error(`Spine rejected the event: ${response.status} ${response.statusText} ${bodyText}`.trim());
65	    }
66	    trace.getActiveSpan()?.setAttribute("card.returned.spine_confirmed", true);
67	    return true;
68	  } catch (error) {
69	    trace.getActiveSpan()?.setAttributes({
70	      "card.returned.spine_confirmed": false,
71	      "spine_send.send_failed": true,
72	      "table.name": tableNameFromSlug(tableId),
73	      "table.slug": tableId,
74	    });
75	    log.warn(
76	      "card.returned send to Spine failed (best-effort; caller decides how to proceed)",
77	      { "table.name": tableNameFromSlug(tableId), "table.slug": tableId },
78	      error
79	    );
80	    return false;
81	  }
82	}
